#!/usr/bin/perl
use strict;
use warnings;
use utf8;

# Check whether $text is a palindrome.
# Lowercase letters are matched, so "Racecar" and "racecar" are the same.
# Spaces, punctuation and other non-letter characters are ignored.
# Empty input is treated as a palindrome, because there's nothing out of order.
sub is_palindrome {
    my ($text) = @_;
    return 1 unless length $text;          # empty string

    my $clean = lc $text;
    $clean =~ s/[^a-z0-9]//g;             # keep only letters and digits

    my $len = length $clean;
    return 1 unless $len;                  # was only whitespace

    my $half = int($len / 2);
    for my $i (0 .. $half - 1) {
        my $j = $len - 1 - $i;
        return 0 if substr($clean, $i, 1) ne substr($clean, $j, 1);
    }
    return 1;
}

# Main program
my $input = do { local $/; <STDIN> };
chomp $input;

if (!defined $input) {
    die "No input provided.\n";
}

print is_palindrome($input)
    ? "The string is a palindrome.\n"
    : "The string is not a palindrome.\n";
```

